    state: "idle",
    stateT: 0,
    animT: 40,
    runPhase: 0,
    devilT: 0,
    godT: 0,
    auraT: 999,
    djumpT: 99,
    landT: 0,
    tumble: 0,
    hw: 15,
    h: 78,
    move: null,
    moveFrame: 0,
    moveActiveEnd: 0,
