var SIGNATURE_VFX = {
  levi: { core: "odmWire", ult: "odmStorm" },
  killua: { core: "zapAura", ult: "godspeedBlur" },
  rengoku: { core: "flameTiger", ult: "flameTrail" },
  madara: { core: "susanooFlare", ult: "susanooFlare" },
  asta: { core: "antiMagic", ult: "voidAura" },
  goku: { core: "kiCharge", ult: "dragonFist" },
  ichigo: { core: "getsuga", ult: "reiatsu" },
  naruto: { core: "cloneEcho", ult: "rasengan" },
  tanjiro: { core: "waterArc", ult: "sunDance" },
  sasuke: { core: "chidori", ult: "amaterasu" },
  luffy: { core: "rubberStretch", ult: "redHawk" },
  zoro: { core: "windCross", ult: "windCross" },
  saitama: { core: "airPressure", ult: "seriousWind" },
  gojo: { core: "limitless", ult: "hollowPurple" },
  yuji: { core: "blackFlash", ult: "cursedFist" },
  deku: { core: "cowlSpark", ult: "smashShock" },
  todoroki: { core: "iceSpires", ult: "flashfire" },
  eren: { core: "hardenCrack", ult: "steamBurst" },
  denji: { core: "sawGrind", ult: "bloodSpray" }
};
function applySignatures(chars) {
  for (const c of chars) {
    const o = OVERRIDES[c.id];
    if (!o) continue;
    Object.assign(c.moves, o.moves);
    const style = SIGNATURE_VFX[c.id];
    if (style) {
      for (const key of ["nspec", "sspec", "dspec"]) if (c.moves[key] && !c.moves[key].vfx) c.moves[key] = { ...c.moves[key], vfx: style.core };
      if (c.moves.ult && !c.moves.ult.vfx) c.moves.ult = { ...c.moves.ult, vfx: style.ult };
    }
    if (o.zone) c.ai.zoneSpec = "nspec";
    for (const [key, a] of Object.entries(o.attach || {})) {
      const m2 = c.moves[key];
      if (!m2) continue;
      const prev = m2.onFrame;
      c.moves[key] = { ...m2, onFrame: (f, fr, g) => {
        if (fr === a.at) a.fn(f, g);
        prev?.(f, fr, g);
      } };
    }
    const m = c.moves;
    c.abilities = [
      { key: "K \xB7 Neutral Special", name: m.nspec.name, desc: m.nspec.desc },
      { key: "K \xB7 Side Special", name: m.sspec.name, desc: m.sspec.desc },
      { key: "K \xB7 Down Special", name: m.dspec.name, desc: m.dspec.desc },
      { key: "L \xB7 Limit Break", name: m.nex.name, desc: `${m.nex.desc} Stances: ${m.sex.name} / ${m.dex.name} / ${m.aex.name}.` },
      { key: "U \xB7 Awaken", name: m.naw.name, desc: `${m.naw.desc} Stances: ${m.saw.name} / ${m.daw.name} / ${m.aaw.name}.` },
      { key: "U \u2192 K \xB7 Awakened", name: m.nfu.name, desc: `${m.nfu.desc} Follow-up variants: ${m.sfu.name}, ${m.dfu.name}, ${m.afu.name}.` },
      { key: "R \xB7 ULTIMATE", name: m.ult.name, desc: m.ult.desc }
    ];
  }
}

