  medium: { react: 13, aggr: 0.65, dodge: 0.28, combo: 0.45, recover: 0.9, special: 0.5, idle: 0.08, precision: 0.75, atkCD: 22 },
  hard: { react: 3, aggr: 0.97, dodge: 0.72, combo: 0.95, recover: 1, special: 0.88, idle: 0, precision: 1, atkCD: 6 }
